  const match = String(rawUrl || '').trim().match(/^([A-Za-z][A-Za-z0-9+.-]*):\/\/([^/?#]+)([^?#]*)(\?[^#]*)?(?:#.*)?$/);
  if (!match) throw new Error('MALFORMED_URL');
  const protocol = match[1].toLowerCase();
  if (protocol !== 'http' && protocol !== 'https') throw new Error('UNSUPPORTED_SOURCE_URL');
  const authority = match[2];
  if (authority.includes('@')) throw new Error('UNSUPPORTED_SOURCE_URL');
