    const lastColon = authority.lastIndexOf(':');
    if (lastColon > 0 && authority.indexOf(':') === lastColon && /^\d+$/.test(authority.slice(lastColon + 1))) {
      host = authority.slice(0, lastColon);
      port = authority.slice(lastColon + 1);
